import os

from flask import app

class Config:
    SECRET_KEY = os.environ.get('SECRET_KEY') or 'a_hard_to_guess_string'
    SQLALCHEMY_DATABASE_URI = os.environ.get('DATABASE_URL') or 'sqlite:///site.db'
    MAIL_SERVER = 'smtp.googlemail.com'
    MAIL_PORT = 587
    MAIL_USE_TLS = True
    MAIL_USERNAME = os.environ.get('EMAIL_USER')
    MAIL_PASSWORD = os.environ.get('EMAIL_PASS')
    SESSION_COOKIE_SECURE = True  # Ensure the session cookie is only sent over HTTPS
    SESSION_COOKIE_SECURE = True  # Use secure cookies (only for HTTPS)
    SESSION_COOKIE_HTTPONLY = True  # Prevent client-side scripts from accessing the cookie
    SESSION_COOKIE_SAMESITE = 'Lax'  # Prevent CSRF attacks

    # Optionally force session to expire when the browser is closed
    PERMANENT_SESSION_LIFETIME = 0


class DevelopmentConfig(Config):
    DEBUG = True

class ProductionConfig(Config):
    DEBUG = False
    SQLALCHEMY_DATABASE_URI = os.environ.get('DATABASE_URL') or 'postgresql://user:password@localhost/prod_db'

# To use these configs, you can modify the __init__.py to choose the appropriate configuration class based on the environment

env = os.environ.get('FLASK_ENV')

if env == 'development':
    app.config.from_object('config.DevelopmentConfig')
elif env == 'production':
    app.config.from_object('config.ProductionConfig')
else:
    app.config.from_object('config.Config')